def knn_vote(train: list[list[float]], labels: list[int], query: list[float], k: int) -> int:
    n: int = len(train)
    dists: list[float] = []
    for r in range(n):
        row: list[float] = train[r]
        width: int = min(len(row), len(query))
        d: float = 0.0
        for c in range(width):
            diff: float = row[c] - query[c]
            d += diff * diff
        dists.append(d)
    kk: int = k
    if k < 0:
        kk = n + k
        if kk < 0:
            kk = 0
    elif k > n:
        kk = n
    taken: list[bool] = []
    for r in range(n):
        taken.append(False)
    votes: dict[int, int] = {}
    order: list[int] = []
    for t in range(kk):
        best: int = -1
        for r in range(n):
            if not taken[r]:
                if best == -1 or dists[r] < dists[best]:
                    best = r
        taken[best] = True
        order.append(best)
        votes[labels[best]] = votes.get(labels[best], 0) + 1
    if len(order) == 0:
        raise ValueError("max() arg is an empty sequence")
    winner: int = -1
    top: int = 0
    for idx in order:
        c2: int = votes.get(labels[idx], 0)
        if c2 > top:
            top = c2
            winner = labels[idx]
    return winner
